import { cn } from "@/lib/utils"
import { LOGO_ART } from "./logo-art"

type LogoVariant = "mini" | "mark" | "seal"

interface LogoProps {
  variant?: LogoVariant
  className?: string
  /** Accessible name; omit when the logo sits next to visible text (decorative). */
  label?: string
}

/**
 * Printer's mark: the Tengger caldera (Batok's gullied dome, Bromo, Semeru) over the sand sea with an italic "Rh".
 * "mini" is inline SVG for small sizes; "mark" and "seal" are cached SVG masks painted with currentColor.
 * Art is generated by scripts/logo/make.mjs.
 */
export function Logo({ variant = "mini", className, label }: Readonly<LogoProps>) {
  const a11y = label ? { role: "img", "aria-label": label } : { "aria-hidden": true as const }

  if (variant === "mini") {
    return (
      <svg
        viewBox="0 0 1000 1000"
        className={cn("shrink-0 text-ink", className)}
        {...a11y}
        dangerouslySetInnerHTML={{ __html: LOGO_ART.mini }}
      />
    )
  }

  return <span className={cn("logo-mask", `logo-mask--${variant}`, "text-ink", className)} {...a11y} />
}
